WFJ.Data.add("book", {
  ["960a0524c5f2dc0c"] = { "Il piano 2 è altrettanto semplice, ma richiederà più pazienza da parte nostra. Il nostro uomo infiltrato a Menethil è già stato pagato per i suoi servigi, e ha avuto un successo brillante. Non dovremmo avere problemi a prendere il nostro bersaglio e a catturarlo una volta salpati.", "." },
  ["963c79c4b8deca99"] = { "Contadino Kalaba\nDebiti insoluti. Pagamento in prodotti agricoli promesso al momento del raccolto.\n\nCittadino Wilkes\nTutti i debiti pagati.\n\nCittadino Bonoan\nTutti i debiti pagati.\n\nMinatore Wellty\nDebito insoluto. Pagamento dovuto alla prossima consegna di minerale da Venazzurra.\n\nMinatore Sidney\nDebito insoluto. Pagamento dovuto alla prossima consegna di minerale da Venazzurra.\n\nMinatore Hackett\nDebito insoluto. Pagamento dovuto alla prossima consegna di minerale da Venazzurra.", "." },
  ["964be78083854584"] = { "Dopo essere sopravvissuto alla fuga dalla ⟦Roland's Doom=Rovina di Roland⟧, mi nascosi in un fienile di proprietà di un uomo di nome Sven. Passai alcuni giorni nel fienile, e un tale orrore mi era rimasto addosso che non mi feci mai vedere da Sven o dalla sua famiglia. Ma da ciò che vidi dal mio nascondiglio, capii che quei contadini erano gente davvero per bene. Se fossi uscito allo scoperto credo che mi avrebbero accolto, ma per me fidarmi è difficile. Ancora di più dopo quello spavento nella miniera.\n\nCosì rimasi nascosto.", "." },
  ["96a997a0ed80ab75"] = { "Throm-Ka, combattente. Non starò a lodare le tue imprese di forza e di valore. Sono storia vecchia. Ucciso qualche umano di recente? Non molti, scommetto. Stai rallentando. Ti stai rammollendo senza una sfida.\n\nMi serve un altro paio di braccia e, checché ne dicano i tuoi leccapiedi, ti serve l'addestramento che posso darti io. Quando te lo sarai ficcato in quella testa dura, ti aspetterò sotto la tettoia appena fuori dall'Antro del Tirocinio.\n\n-Frang, istruttore dei guerrieri", "." },
  ["96aac497d28b387b"] = { "Come si è detto, alcuni worgen sono esperti nelle arti mistiche, e la loro magia è fatta di oscurità e corruzione.\n\nMaledizioni e veleni soprannaturali sono comuni, perciò occorre essere avvertiti: chi affronta i maghi worgen dovrebbe armarsi di protezioni contro l'ombra.", "." },
})
